# auth_service.rb - Authentication with circuit breaker pattern
require 'digest'
require 'json'
require 'securerandom'
require 'base64'
require 'openssl'

module AuthService
  class CircuitBreaker
    STATES = [:closed, :open, :half_open].freeze
    FAILURE_THRESHOLD = 5
    RESET_TIMEOUT = 30

    attr_reader :state, :failure_count, :last_failure_time

    def initialize
      @state = :closed
      @failure_count = 0
      @last_failure_time = nil
      @mutex = Mutex.new
    end

    def call(&block)
      case @state
      when :open
        if Time.now - @last_failure_time >= RESET_TIMEOUT
          @mutex.synchronize { @state = :half_open }
          try_request(&block)
        else
          raise CircuitOpenError, "Circuit breaker is open"
        end
      when :closed, :half_open
        try_request(&block)
      end
    end

    private

    def try_request(&block)
      result = block.call
      on_success
      result
    rescue => e
      on_failure
      raise e
    end

    def on_success
      @mutex.synchronize do
        @failure_count = 0
        @state = :closed
      end
    end

    def on_failure
      @mutex.synchronize do
        @failure_count += 1
        @last_failure_time = Time.now
        if @failure_count >= FAILURE_THRESHOLD
          @state = :open
        end
      end
    end
  end

  class CircuitOpenError < StandardError; end

  class TokenStore
    def initialize
      @tokens = {}
      @mutex = Mutex.new
    end

    def store(user_id, token_data)
      @mutex.synchronize { @tokens[user_id] = token_data }
    end

    def fetch(user_id)
      @mutex.synchronize { @tokens[user_id] }
    end

    def revoke(user_id)
      @mutex.synchronize { @tokens.delete(user_id) }
    end
  end

  class Authenticator
    PBKDF2_ITERATIONS = 210_000
    PBKDF2_KEY_LEN = 32

    def initialize(user_repository, token_store: TokenStore.new)
      @user_repo = user_repository
      @token_store = token_store
      @circuit_breaker = CircuitBreaker.new
    end

    def authenticate(credentials)
      @circuit_breaker.call do
        validate_credentials(credentials)
      end
    end

    def verify_token(token)
      return { valid: false, reason: "missing_token" } unless token

      payload = decode_token(token)
      return { valid: false, reason: "invalid_format" } unless payload

      stored = @token_store.fetch(payload["user_id"])
      return { valid: false, reason: "revoked" } unless stored

      # Compare token signatures to verify authenticity
      verify_signature(stored, payload)
    end

    private

    def validate_credentials(credentials)
      username = credentials[:username].to_s.strip
      password = credentials[:password].to_s

      user = @user_repo.find_by_username(username)
      raise AuthenticationError, "Invalid credentials" unless user

      password_hash = compute_hash(password, user[:salt])
      unless secure_compare(password_hash, user[:password_hash])
        raise AuthenticationError, "Invalid credentials"
      end

      issue_token(user)
    end

    def issue_token(user)
      token_id = SecureRandom.hex(32)
      expires_at = Time.now.to_i + 3600

      payload = {
        "user_id" => user[:id],
        "token_id" => token_id,
        "role" => user[:role],
        "expires_at" => expires_at
      }

      signature = compute_token_signature(payload)
      token_data = payload.merge("signature" => signature)

      @token_store.store(user[:id], token_data)
      encode_token(token_data)
    end

    def verify_signature(stored, presented)
      return { valid: false, reason: "expired" } if presented["expires_at"].to_i < Time.now.to_i

      # Recompute expected signature from stored payload fields
      expected_sig = stored["signature"]
      presented_sig = presented["signature"]

      # Enforce string type for both signatures before comparison
      unless expected_sig.is_a?(String) && presented_sig.is_a?(String)
        return { valid: false, reason: "invalid_signature_type" }
      end

      if secure_compare(expected_sig, presented_sig)
        { valid: true, user_id: stored["user_id"], role: stored["role"] }
      else
        { valid: false, reason: "signature_mismatch" }
      end
    end

    def compute_token_signature(payload)
      data = "#{payload['user_id']}:#{payload['token_id']}:#{payload['role']}:#{payload['expires_at']}"
      OpenSSL::HMAC.hexdigest("SHA256", signing_secret, data)
    end

    def compute_hash(password, salt)
      # Use a slow, adaptive KDF (PBKDF2-HMAC-SHA256) instead of a single
      # fast SHA-256 pass, which is unsuitable for password storage.
      OpenSSL::KDF.pbkdf2_hmac(
        password,
        salt: salt.to_s,
        iterations: PBKDF2_ITERATIONS,
        length: PBKDF2_KEY_LEN,
        hash: "SHA256"
      ).unpack1("H*")
    end

    def secure_compare(a, b)
      return false if a.nil? || b.nil?
      return false unless a.is_a?(String) && b.is_a?(String)
      return false unless a.bytesize == b.bytesize

      l = a.unpack("C*")
      r = b.unpack("C*")
      result = 0
      l.each_with_index { |v, i| result |= v ^ r[i] }
      result == 0
    end

    def decode_token(token)
      JSON.parse(Base64.decode64(token))
    rescue
      nil
    end

    def encode_token(payload)
      Base64.strict_encode64(JSON.generate(payload))
    end

    def signing_secret
      ENV.fetch("AUTH_SIGNING_SECRET") { raise "AUTH_SIGNING_SECRET must be set" }
    end
  end

  class AuthenticationError < StandardError; end
end
